function renderCompactCylinderSvg(liquidTopY, guideY = null) {
  const guideLine = guideY === null
    ? ''
    : `<line x1="6" y1="${guideY}" x2="24" y2="${guideY}" stroke="#b91c1c" stroke-width="1.5" stroke-dasharray="3 3"/>`;

  return `<svg class="svg-prob" viewBox="0 0 130 260" width="110" height="220" xmlns="http://www.w3.org/2000/svg" style="display:block;margin:0.5rem auto">
    <title>Graduated cylinder showing liquid level</title>
    <rect width="130" height="260" rx="20" fill="#f8fbff"/>
    <rect x="12" y="12" width="106" height="236" rx="16" fill="#ffffff" stroke="#cbd5e1" stroke-width="1.5"/>
    <rect x="25" y="15" width="72" height="228" rx="10" fill="#eff6ff" stroke="#93c5fd" stroke-width="1.5"/>
    <path d="M27,${liquidTopY} Q61,${liquidTopY + 14} 95,${liquidTopY} L95,243 L27,243 Z" fill="#93c5fd" opacity="0.55"/>
    <path d="M27,${liquidTopY} Q61,${liquidTopY + 14} 95,${liquidTopY}" fill="none" stroke="#2563eb" stroke-width="1.4" opacity="0.92"/>
    <g stroke="#64748b" stroke-width="1" font-family="Arial, Helvetica, sans-serif" font-size="9" fill="#334155" text-anchor="start">
      <line x1="25" y1="225" x2="45" y2="225"/><text x="48" y="229">10</text>
      <line x1="25" y1="193" x2="38" y2="193"/>
      <line x1="25" y1="161" x2="45" y2="161"/><text x="48" y="165">30</text>
      <line x1="25" y1="129" x2="38" y2="129"/>
      <line x1="25" y1="97" x2="45" y2="97"/><text x="48" y="101">50</text>
      <line x1="25" y1="65" x2="38" y2="65"/>
      <line x1="25" y1="33" x2="45" y2="33"/><text x="48" y="37">70</text>
      <line x1="25" y1="209" x2="32" y2="209"/>
      <line x1="25" y1="177" x2="32" y2="177"/>
      <line x1="25" y1="145" x2="32" y2="145"/>
      <line x1="25" y1="113" x2="32" y2="113"/>
      <line x1="25" y1="81" x2="32" y2="81"/>
      <line x1="25" y1="49" x2="32" y2="49"/>
    </g>
    <rect x="25" y="15" width="72" height="228" rx="10" fill="none" stroke="#60a5fa" stroke-width="1.8"/>
    ${guideLine}
  </svg>`;
}

