function renderBalanceSvg(displayValue) {
  return `<svg class="svg-prob" viewBox="0 0 280 120" width="240" height="100" xmlns="http://www.w3.org/2000/svg" style="display:block;margin:0.5rem auto">
    <title>Electronic balance displaying ${displayValue} g</title>
    <rect width="280" height="120" rx="18" fill="#f8fbff"/>
    <rect x="5" y="5" width="270" height="110" rx="14" fill="#ffffff" stroke="#cbd5e1" stroke-width="2"/>
    <rect x="15" y="15" width="250" height="55" rx="9" fill="#eff6ff" stroke="#93c5fd" stroke-width="1.5"/>
    <text x="247" y="57" font-family="Arial, Helvetica, sans-serif" font-size="33" font-weight="700" fill="#1d4ed8" text-anchor="end" letter-spacing="1">${displayValue}</text>
    <text x="256" y="57" font-family="Arial, Helvetica, sans-serif" font-size="14" font-weight="700" fill="#0369a1" text-anchor="start">g</text>
    <rect x="15" y="78" width="250" height="28" rx="7" fill="#f8fafc" stroke="#cbd5e1" stroke-width="1"/>
    <rect x="25" y="84" width="44" height="16" rx="4" fill="#dbeafe"/><text x="47" y="96" font-family="Arial, Helvetica, sans-serif" font-size="8.5" font-weight="700" fill="#1d4ed8" text-anchor="middle">ON/OFF</text>
    <rect x="78" y="84" width="34" height="16" rx="4" fill="#dbeafe"/><text x="95" y="96" font-family="Arial, Helvetica, sans-serif" font-size="8.5" font-weight="700" fill="#1d4ed8" text-anchor="middle">TARE</text>
    <rect x="121" y="84" width="34" height="16" rx="4" fill="#dbeafe"/><text x="138" y="96" font-family="Arial, Helvetica, sans-serif" font-size="8.5" font-weight="700" fill="#1d4ed8" text-anchor="middle">MODE</text>
    <rect x="164" y="84" width="34" height="16" rx="4" fill="#dbeafe"/><text x="181" y="96" font-family="Arial, Helvetica, sans-serif" font-size="8.5" font-weight="700" fill="#1d4ed8" text-anchor="middle">CAL</text>
  </svg>`;
}

export const ALL_PROBLEMS = [
  {id:'p01',difficulty:'easy',type:'concept',tag:'Concept',q:'Which statement correctly describes chemistry as the <em>central science</em>?',choices:['Chemistry only studies synthetic materials.','Chemistry connects physics at the atomic scale with biology at the living-systems level, making it relevant to all sciences.','Chemistry is a branch of physics with no connection to biology.','Biology is more central because it studies all living things.'],correct:1,solution:'Chemistry is called the central science because it connects the physical sciences to the life sciences. Physics explains matter and energy, while biology depends on chemical reactions inside living systems.<br><br>That is why ideas from chemistry show up in medicine, environmental science, geology, engineering, and more.'},
  {id:'p02',difficulty:'easy',type:'concept',tag:'Concept',q:'A student notices a yellow, flickering Bunsen burner flame. What should they do first?',choices:['Increase the gas flow to make the flame larger.','Open the air vent collar to increase airflow until the flame turns blue.','Place a beaker of water over the flame to cool it down.','Add wire gauze under the beaker immediately.'],correct:1,solution:'A yellow flame = incomplete combustion = not enough air. Opening the air vent increases oxygen flow, producing a hotter, cleaner, blue flame. Yellow flames deposit soot and are harder to control.'},
  {id:'p03',difficulty:'easy',type:'concept',tag:'Concept',q:'When reading volume in a graduated cylinder, you should read from the:',choices:['Top of the meniscus from above.','Bottom of the meniscus at eye level.','Middle of the meniscus from any angle.','Side of the cylinder at any height.'],correct:1,solution:'Water forms a concave meniscus. Read from the BOTTOM of the curve at eye level. Reading from above inflates the reading; from below deflates it.'},
  {id:'p04',difficulty:'easy',type:'concept',tag:'Concept',q:'Which equipment combination supports a beaker above a Bunsen burner and distributes heat evenly?',choices:['Test tube and crucible tongs','Beaker and wash bottle','Iron ring and wire gauze','Erlenmeyer flask and ring stand alone'],correct:2,solution:'The iron ring (on ring stand) holds wire gauze above the burner. The gauze distributes heat evenly under the beaker, preventing cracking from hot spots.'},
  {id:'p05',difficulty:'easy',type:'concept',tag:'Concept',q:'A student needs to measure exactly 37.5 mL of water. The best tool is:',choices:['A 100 mL beaker','A 50 mL Erlenmeyer flask','A 50 mL graduated cylinder','A 250 mL round-bottom flask'],correct:2,solution:'Only the graduated cylinder provides accurate volume measurement. Beakers and flasks have approximate markings (±5–10%) and are not suitable for precision measurement.'},
  {id:'p06',difficulty:'easy',type:'concept',tag:'Concept',q:'The GHS skull-and-crossbones symbol on a chemical label indicates:',choices:['The substance is flammable.','The substance is acutely toxic — even small amounts can cause death or serious harm.','The substance is a mild irritant.','The substance corrodes metals.'],correct:1,solution:'Skull-and-crossbones (GHS06) = acute toxicity. The chemical can be lethal through ingestion, skin contact, or inhalation even in small quantities. Examples: mercury compounds, cyanide.'},
  {id:'p07',difficulty:'easy',type:'concept',tag:'Concept',q:'Before measuring mass on a triple-beam balance, the first step is to:',choices:['Place the chemical directly on the pan.','Tare the balance with weighing paper on the pan, then zero it.','Weigh the chemical in a wet beaker.','Set all riders to maximum.'],correct:1,solution:'Taring: place the empty container/paper first, zero the balance, then add chemical. This ensures you measure only the chemical\'s mass. Never place chemicals directly on the pan — they can corrode it.'},
  {id:'p08',difficulty:'easy',type:'concept',tag:'Concept',q:'A student smells an unknown chemical by holding the open bottle under their nose and inhaling deeply. This is:',choices:['Acceptable for low-hazard chemicals.','The standard technique for identification.','A safety violation — the correct method is wafting.','Only a problem in advanced labs.'],correct:2,solution:'Direct inhalation can expose you to toxic concentrations. Wafting is safe: hold the container at arm\'s length and gently fan vapor toward your nose.'},
  {id:'p09',difficulty:'easy',type:'concept',tag:'Concept',q:'A chemical spills on a student\'s forearm. The immediate correct response is:',choices:['Pat dry quickly with paper towel.','Flush with large amounts of water for at least 15 minutes and alert the teacher.','Apply a neutralizing base to counteract the acid.','Cover with the lab coat and continue working.'],correct:1,solution:'The first step is always to flush the area with lots of water for at least 15 minutes. Water dilutes and removes the chemical before it can keep burning the skin.<br><br>Do not try to neutralize the spill yourself. Acid-base reactions can release heat and make the injury worse. Alert the teacher while you are flushing.'},
  {id:'p10',difficulty:'easy',type:'concept',tag:'Concept',q:'Crucible tongs are designed for handling:',choices:['Test tubes during heating.','Large Erlenmeyer flasks.','Hot crucibles and evaporating dishes.','Gas valves on the ring stand.'],correct:2,solution:'Crucible tongs have curved jaws for gripping the rim of a crucible or evaporating dish. Use a test-tube clamp for test tubes; hot mitts for large glassware.'},
  {id:'p11',difficulty:'easy',type:'concept',tag:'Concept',q:'Which statement about chemistry is most accurate?',choices:['Chemistry only studies liquid and gaseous matter.','Chemistry only applies to synthetic materials.','Chemistry is the study of matter — its composition, properties, and changes — in all states.','Chemistry is a subset of biology.'],correct:2,solution:'Chemistry covers all forms of matter (solid, liquid, gas, plasma), natural and synthetic, from atoms to industrial processes.'},
  {id:'p12',difficulty:'easy',type:'concept',tag:'Concept',q:'Which branch of chemistry studies chemical processes in living organisms like enzyme reactions and DNA replication?',choices:['Analytical chemistry','Organic chemistry','Biochemistry','Physical chemistry'],correct:2,solution:'Biochemistry is the chemistry of life — proteins, carbohydrates, lipids, nucleic acids, and their reactions in living cells. It is the chemical foundation of biology and medicine.'},
  {id:'p13',difficulty:'easy',type:'calc',tag:'Calculation',q:'Express 6,020,000 in scientific notation.',answer:'6.02e6',isText:true,solution:'Move decimal 6 places left: 6,020,000 → 6.02. Exponent = +6. Answer: 6.02 × 10^6'},
  {id:'p14',difficulty:'easy',type:'calc',tag:'Calculation',q:'Express 0.000456 in scientific notation.',answer:'4.56e-4',isText:true,solution:'Move decimal 4 places right (< 1 → negative exponent): 0.000456 → 4.56 × 10^-4'},
  {id:'p15',difficulty:'easy',type:'calc',tag:'Calculation',q:'Convert 1.75 × 10<sup>5</sup> to standard notation.',answer:'175000',isText:true,solution:'Positive exponent: move decimal right 5 places. 1.75 → 175,000'},
  {id:'p16',difficulty:'easy',type:'calc',tag:'Calculation',q:'Convert 3.20 × 10<sup>-3</sup> to standard notation.',answer:'0.00320',isText:true,solution:'Negative exponent: move decimal left 3 places. 3.20 → 0.00320. Trailing zero is significant.'},
  {id:'p17',difficulty:'easy',type:'calc',tag:'Calculation',q:'Express 0.00823 in scientific notation.',answer:'8.23e-3',isText:true,solution:'Move decimal 3 places right: 0.00823 → 8.23 × 10^-3'},
  {id:'p18',difficulty:'medium',type:'concept',tag:'Concept',q:'How many significant figures does 0.00450 contain?',choices:['2','3','4','5'],correct:1,solution:'Leading zeros are not significant (placeholders). Significant digits: 4, 5, and trailing 0 = 3 sig figs.'},
  {id:'p19',difficulty:'medium',type:'concept',tag:'Concept',q:'How many significant figures does 4.050 × 10<sup>3</sup> contain?',choices:['2','3','4','5'],correct:2,solution:'4 (nonzero ✓), 0 (captive ✓), 5 (nonzero ✓), 0 (trailing after decimal ✓) → 4 sig figs.'},
  {id:'p20',difficulty:'medium',type:'concept',tag:'Concept',q:'A calculator shows 5.876 for 4.52 × 1.3. The correctly rounded answer is:',choices:['5.9','5.88','5.876','6.0'],correct:0,solution:'Multiplication: fewest sig figs wins. 4.52 has 3; 1.3 has 2. Round to 2: 5.876 → 5.9'},
  {id:'p21',difficulty:'medium',type:'concept',tag:'Concept',q:'Which number unambiguously has exactly three significant figures?',choices:['1200','120.0','1.20 × 10^2','1.2 × 10^3'],correct:2,solution:'1200 ambiguous. 120.0 has 4. 1.20 × 10^2 clearly has 3 (1, 2, trailing 0 after decimal). Scientific notation eliminates ambiguity.'},
  {id:'p22',difficulty:'medium',type:'multi',tag:'Multi-step',q:'Mass1 = 25.38 g, Mass2 = 4.1 g. What is the total mass with correct sig figs?',answer:'29.5',tolerance:0.05,solution:'Addition: fewest decimal places. 25.38 (2 dp) + 4.1 (1 dp) → round to 1 dp: 29.48 → 29.5 g'},
  {id:'p23',difficulty:'medium',type:'calc',tag:'Calculation',q:'Convert 3.50 km to centimeters.',answer:'350000',tolerance:1,solution:'Start with the metric ladder: km → m → cm.<br><br>3.50 km × (1000 m / 1 km) × (100 cm / 1 m) = 350,000 cm = 3.50 × 10^5 cm.<br><br>The answer keeps 3 significant figures because the given value, 3.50 km, has 3 sig figs.'},
  {id:'p24',difficulty:'easy',type:'calc',tag:'Calculation',q:'Convert 2.75 L to milliliters.',answer:'2750',tolerance:0.5,solution:'2.75 L × (1000 mL/L) = 2750 mL (3 sig figs)'},
  {id:'p25',difficulty:'easy',type:'calc',tag:'Calculation',q:'Convert 6.50 g to milligrams.',answer:'6500',tolerance:0.5,solution:'6.50 g × (1000 mg/g) = 6500 mg = 6.50 × 10^3 mg (3 sig figs)'},
  {id:'p26',difficulty:'easy',type:'calc',tag:'Calculation',q:'Convert 3.00 days to hours.',answer:'72.0',tolerance:0.1,solution:'3.00 days × (24 hr/day) = 72.0 hr (3 sig figs)'},
  {id:'p27',difficulty:'easy',type:'calc',tag:'Calculation',q:'Convert 12.0 inches to centimeters. (1 in = 2.54 cm)',answer:'30.5',tolerance:0.1,solution:'12.0 in × (2.54 cm/in) = 30.48 → 30.5 cm (3 sig figs)'},
  {id:'p28',difficulty:'hard',type:'multi',tag:'Multi-step',q:'How many seconds in exactly 5.00 years? (365 days/year) Enter in scientific notation, e.g. 1.58e8.',answer:'1.58e8',isText:true,solution:'<p>Convert using a chain of unit factors:</p><p>5.00 yr × (365 d/yr) × (24 hr/d) × (60 min/hr) × (60 s/min)</p><p>= 157,680,000 s = <strong>1.58 × 10^8 s</strong> (3 sig figs)</p>'},
  {id:'p29',difficulty:'medium',type:'multi',tag:'Multi-step',q:'A marathon is 26.2 miles. Convert to km. (1 mile = 1.609 km)',answer:'42.2',tolerance:0.2,solution:'26.2 mi × (1.609 km/mi) = 42.156 → 42.2 km (3 sig figs)'},
  {id:'p30',difficulty:'easy',type:'calc',tag:'Calculation',q:'Convert 4.20 m to millimeters.',answer:'4200',tolerance:0.5,solution:'4.20 m × (1000 mm/m) = 4200 mm = 4.20 × 10^3 mm (3 sig figs)'},
  {id:'p31',difficulty:'easy',type:'multi',tag:'Multi-step',q:'Convert 850 m to kilometers.',answer:'0.850',tolerance:0.001,solution:'850 m × (1 km/1000 m) = 0.850 km. Trailing zero is significant — shows 3 sig figs.'},
  {id:'p32',difficulty:'easy',type:'calc',tag:'Calculation',q:'Convert 37.0°C (body temperature) to °F. (°F = °C × 9/5 + 32)',answer:'98.6',tolerance:0.1,solution:'°F = (37.0 × 1.8) + 32 = 66.6 + 32 = 98.6°F'},
  {id:'p33',difficulty:'easy',type:'calc',tag:'Calculation',q:'Convert 25°C to Kelvin. (K = °C + 273)',answer:'298',tolerance:1,solution:'K = 25 + 273 = 298 K'},
  {id:'p34',difficulty:'easy',type:'calc',tag:'Calculation',q:'Convert 72°F to °C. (°C = (°F - 32) × 5/9)',answer:'22',tolerance:0.5,solution:'°C = (72 - 32) × 5/9 = 40 × 0.5556 = 22.2°C, which rounds to 22°C for 2 significant figures'},
  {id:'p35',difficulty:'easy',type:'calc',tag:'Calculation',q:'Convert -40°C to Kelvin.',answer:'233',tolerance:1,solution:'K = -40 + 273 = 233 K'},
  {id:'p36',difficulty:'easy',type:'calc',tag:'Calculation',q:'A metal has mass = 45.0 g and volume = 15.0 mL. Calculate density in g/mL.',answer:'3.00',tolerance:0.02,solution:'D = m/V = 45.0/15.0 = 3.00 g/mL (3 sig figs)'},
  {id:'p37',difficulty:'medium',type:'multi',tag:'Multi-step',q:'Metal (mass = 28.5 g) placed in a cylinder with 20.0 mL water; water rises to 30.0 mL. What is the density?',answer:'2.85',tolerance:0.02,solution:'V = 30.0 - 20.0 = 10.0 mL. D = 28.5/10.0 = 2.85 g/mL'},
  {id:'p38',difficulty:'easy',type:'calc',tag:'Calculation',q:'What volume of a substance with density 2.60 g/mL has a mass of 52.0 g?',answer:'20.0',tolerance:0.1,solution:'V = m/D = 52.0/2.60 = 20.0 mL (3 sig figs)'},
  {id:'p39',difficulty:'easy',type:'calc',tag:'Calculation',q:'What is the mass of 25.0 mL of ethanol? (Density = 0.789 g/mL)',answer:'19.7',tolerance:0.1,solution:'m = D × V = 0.789 × 25.0 = 19.725 → 19.7 g (3 sig figs)'},
  {id:'p40',difficulty:'easy',type:'concept',tag:'Concept',q:'Iron (density = 7.87 g/mL) is placed in water (density = 1.00 g/mL). It will:',choices:['Float because metals look lighter than they are.','Sink because its density is greater than water\'s.','Dissolve slowly over time.','Float because water pressure is equal from all sides.'],correct:1,solution:'Objects sink when denser than the fluid. Iron (7.87) >> water (1.00) → sinks. Objects float when less dense than the fluid — wood (≈0.5 g/mL) floats.'},
  {id:'p41',difficulty:'medium',type:'multi',tag:'Multi-step',q:'Student measures g = 9.71 m/s^2. Accepted = 9.81 m/s^2. Percent error = |exp - accepted| / accepted × 100%.',answer:'1.02',tolerance:0.05,solution:'<p>Use the percent error formula: % error = |exp - accepted| / accepted × 100%.</p><p>% error = |9.71 - 9.81| / 9.81 × 100% = 0.10 / 9.81 × 100% = <strong>1.02%</strong></p><p>The absolute value keeps percent error positive.</p>'},
  {id:'p42',difficulty:'medium',type:'multi',tag:'Multi-step',q:'Student measures 4.85 g; true mass is 5.00 g. What is the percent error?',answer:'3.0',tolerance:0.1,solution:'% error = |4.85-5.00|/5.00 × 100% = 0.15/5.00 × 100% = 3.0%'},
  {id:'p43',difficulty:'medium',type:'multi',tag:'Multi-step',q:'A student writes "35 mL" when the cylinder clearly reads 35.0 mL. The consequence is:',choices:['No difference — both are the same value.','35 has 2 sig figs; 35.0 has 3. The student lost a sig fig of precision.','35.0 is more accurate because it has an extra digit.','35 is more precise because it avoids an estimated digit.'],correct:1,solution:'35 implies measurement to the ones place (2 sig figs). 35.0 shows the tenths digit was estimated (3 sig figs). The trailing zero carries real information about measurement precision.'},
  {id:'p44',difficulty:'easy',type:'concept',tag:'Concept',q:'When preparing a dilute acid, the correct procedure is:',choices:['Add water to acid quickly.','Add acid to water slowly, with stirring.','Mix them simultaneously from two containers.','Heat the acid first, then add water.'],correct:1,solution:'Always add acid to water (AAA rule). Water added to concentrated acid causes violent spattering from extreme localized heat. Adding acid slowly to water distributes heat safely.'},

  // ── GRADUATED CYLINDER READING (SVG) ──
  {id:'p45',difficulty:'medium',type:'concept',tag:'Graduated Cylinder',q:`What volume is shown in this graduated cylinder? Read from the bottom of the meniscus.<br>${renderCompactCylinderSvg(176.4, 183.4)}`,choices:['20.0 mL','23.0 mL','25.0 mL','27.0 mL'],correct:1,solution:'The bottom of the meniscus (red line) sits between the 20 mL and 25 mL marks, closer to 25 mL. Estimating one digit between the marked divisions gives 23.0 mL. Always read at eye level from the bottom of the curve.'},

  {id:'p46',difficulty:'easy',type:'concept',tag:'Graduated Cylinder',q:`What volume is shown in this graduated cylinder?<br>${renderCompactCylinderSvg(90, 97)}`,choices:['48.0 mL','50.0 mL','52.0 mL','54.0 mL'],correct:1,solution:'The meniscus bottom sits exactly on the 50 mL major line. Reading: 50.0 mL. The trailing zero matters — it shows you estimated the tenths digit and it was zero, giving 3 significant figures.'},

  {id:'p47',difficulty:'medium',type:'concept',tag:'Graduated Cylinder',q:`What volume does this graduated cylinder show?<br>${renderCompactCylinderSvg(45.2, 52.2)}`,choices:['58.0 mL','62.0 mL','64.0 mL','66.0 mL'],correct:2,solution:'The meniscus bottom is between the 60 mL and 65 mL marks, closer to 65 mL. Estimating one digit between the marked divisions gives 64.0 mL.'},

  {id:'p48',difficulty:'medium',type:'concept',tag:'Graduated Cylinder',q:`A student reads this graduated cylinder from slightly above eye level. Their reading will be:<br>${renderCompactCylinderSvg(122)}`,choices:['Correct — eye level doesn\'t affect the reading.','Too high — they see the curved top of the meniscus and record more than the true volume.','Too low — they see only part of the meniscus curve.','Too high — reading from above makes the bottom of the meniscus appear lower.'],correct:1,solution:'Reading from above causes you to see the top of the meniscus curve rather than the bottom. This makes the liquid level appear higher than it truly is, so you record a volume that is too large. Always position your eyes exactly level with the meniscus.'},

  // ── ELECTRONIC BALANCE READING ──
  {id:'p49',difficulty:'easy',type:'concept',tag:'Balance Reading',q:'An electronic balance displays the following reading. What mass should be recorded?<br><div class="balance-display">23.470 <span class="balance-unit">g</span></div>',choices:['23.47 g','23.470 g','23.5 g','0.02347 kg'],correct:1,solution:'Record exactly what the balance shows: 23.470 g. The trailing zero is significant — it tells you the balance measures to the thousandths place (±0.001 g). Dropping it to 23.47 g would misrepresent the precision of the instrument.'},

  {id:'p50',difficulty:'medium',type:'concept',tag:'Balance Reading',q:'A student places a beaker on the balance, tares it to 0.000 g, then adds chemical until the display reads:<br><div class="balance-display">5.320 <span class="balance-unit">g</span></div>How many significant figures does this measurement have?',choices:['3','4','5','2'],correct:1,solution:'5.320 g has 4 significant figures: 5 (nonzero ✓), 3 (nonzero ✓), 2 (nonzero ✓), trailing 0 after decimal ✓. The trailing zero is significant because the balance resolved that digit — it is not a placeholder.'},

  {id:'p51',difficulty:'medium',type:'concept',tag:'Balance Reading',q:'A balance displays this reading. A student writes down "0.8 g" in their lab notebook.<br><div class="balance-display">0.820 <span class="balance-unit">g</span></div>What is wrong with recording "0.8 g"?',choices:['Nothing — 0.8 g and 0.820 g are the same value.','The student lost 2 significant figures of precision that the balance actually measured.','0.8 g has too many sig figs for this balance.','The student should have recorded it in kg instead.'],correct:1,solution:'The balance measured to the thousandths place and showed 0.820 g (3 sig figs). Recording "0.8 g" keeps only 1 sig fig, discarding the real precision of the instrument. In chemistry, the number of digits you write always communicates how precisely something was measured.'},

  // ── MORE CONCEPT — Lab Safety & Hazards ──
  {id:'p52',difficulty:'easy',type:'concept',tag:'Safety/GHS',q:'Which PPE (personal protective equipment) is required at all times in a chemistry laboratory?',choices:['Gloves only','Safety goggles only','Safety goggles and a lab coat (or apron)','A face shield and steel-toed shoes'],correct:2,solution:'Safety goggles protect against chemical splashes and flying debris. A lab coat or apron protects skin and clothing. These are the minimum required PPE for any chemistry lab. Gloves are used for specific hazards but are not always worn for every experiment.'},

  {id:'p53',difficulty:'easy',type:'concept',tag:'Safety/GHS',q:'A student\'s long hair catches fire from a Bunsen burner. The best immediate response is:',choices:['Pour water from the nearest beaker over their head.','Use the fire blanket to smother the flames and activate the safety shower.','Blow out the flames quickly.','Fan the area with a notebook to reduce oxygen supply.'],correct:1,solution:'A fire blanket smothers flames by cutting off oxygen. The safety shower delivers large volumes of water to drench the affected area. Never blow on flames (adds oxygen) or use small containers of water (insufficient volume). Alert the teacher and activate the emergency shower immediately.'},

  {id:'p54',difficulty:'easy',type:'concept',tag:'Balance Reading',q:'What does it mean to "tare" a balance?',choices:['To calibrate the balance using a known mass.','To zero the balance with the empty container on the pan, so only the chemical\'s mass is recorded.','To clean the balance pan with distilled water.','To record the mass of the container alone for subtraction later.'],correct:1,solution:'Taring electronically zeros the balance with the container already on the pan. When you add chemical, the display shows only the chemical\'s mass. This is faster and less error-prone than subtracting the container mass manually.'},

  {id:'p55',difficulty:'easy',type:'concept',tag:'Safety/GHS',q:'Which of the following is NOT a correct laboratory safety rule?',choices:['Tie back long hair before using a Bunsen burner.','Read the entire procedure before beginning.','Taste a small amount of an unknown substance to help identify it.','Report all accidents, including minor spills, to the teacher immediately.'],correct:2,solution:'Never taste chemicals in a laboratory — even substances that appear safe can be toxic or contaminated. The other options are all legitimate safety rules. Identify unknown substances through approved chemical tests, not sensory methods.'},

  {id:'p56',difficulty:'easy',type:'concept',tag:'Safety/GHS',q:'The GHS flame symbol on a chemical container indicates:',choices:['The substance reacts violently with water.','The substance is flammable or self-heating and may catch fire easily.','The substance is extremely corrosive to metals.','The substance releases toxic gas when heated.'],correct:1,solution:'The GHS flame symbol (GHS02) marks flammable liquids, solids, gases, or self-heating substances. These materials ignite easily and should be kept away from open flames, sparks, and heat sources. Examples: ethanol, acetone, hexane.'},

  {id:'p57',difficulty:'easy',type:'concept',tag:'Safety/GHS',q:'What is the purpose of a fume hood in a chemistry laboratory?',choices:['To keep chemicals at a constant temperature.','To provide ventilation that draws hazardous vapors away from the user.','To store reactive chemicals safely between uses.','To filter dust from the air before it settles on sensitive equipment.'],correct:1,solution:'A fume hood uses continuous airflow to draw toxic, flammable, or irritating vapors away from the chemist\'s breathing zone and exhaust them safely. Any experiment generating harmful vapors, gases, or dust must be conducted in a fume hood.'},

  {id:'p58',difficulty:'medium',type:'concept',tag:'Concept',q:'Which glassware is most appropriate for measuring 25.00 mL of a solution as accurately as possible?',choices:['250 mL beaker','100 mL Erlenmeyer flask','25 mL volumetric pipette','25 mL graduated cylinder'],correct:2,solution:'A volumetric pipette is calibrated to deliver exactly one specific volume (here, 25.00 mL) with 4 significant figures of precision. A graduated cylinder is good but only reads to 3 sig figs. Beakers and flasks have ±5–10% error and are not precision measurement tools.'},

  {id:'p59',difficulty:'easy',type:'concept',tag:'Concept',q:'After heating a crucible, you want to pick it up. The correct tool is:',choices:['Your gloved hand','Crucible tongs','Beaker tongs','A wooden splint'],correct:1,solution:'Crucible tongs are specifically shaped to grip the rim of a crucible. Hot crucibles can cause severe burns — gloves alone are insufficient for high-temperature items. Beaker tongs grip cylindrical glassware, not the flat-rimmed crucible.'},

  // ── MORE CALC — Scientific Notation ──
  {id:'p60',difficulty:'medium',type:'calc',tag:'Calculations/Scientific Notation',q:'Multiply (2.0 × 10^3) × (4.0 × 10^2). Express in scientific notation.',answer:'8.0e5',isText:true,solution:'Multiply coefficients: 2.0 × 4.0 = 8.0. Add exponents: 3 + 2 = 5. Answer: 8.0 × 10^5. Sig figs: limited by 2 sig figs in each factor → 8.0 × 10^5'},
  {id:'p61',difficulty:'medium',type:'calc',tag:'Calculations/Scientific Notation',q:'Divide (9.0 × 10^6) ÷ (3.0 × 10^2). Express in scientific notation.',answer:'3.0e4',isText:true,solution:'Divide coefficients: 9.0 ÷ 3.0 = 3.0. Subtract exponents: 6 - 2 = 4. Answer: 3.0 × 10^4'},
  {id:'p62',difficulty:'easy',type:'calc',tag:'Calculations/Scientific Notation',q:'Express 0.000000720 in scientific notation.',answer:'7.20e-7',isText:true,solution:'Move decimal 7 places right (< 1 → negative exponent): 0.000000720 → 7.20 × 10^-7. The trailing zero in 7.20 is significant — do not drop it.'},
  {id:'p63',difficulty:'easy',type:'calc',tag:'Calculations/Scientific Notation',q:'Convert 4.50 × 10^-2 to standard notation.',answer:'0.0450',isText:true,solution:'Negative exponent: move decimal left 2 places. 4.50 → 0.0450. Keep trailing zero — it is significant.'},
  {id:'p64',difficulty:'medium',type:'calc',tag:'Calculations/Scientific Notation',q:'Express 100,500 in scientific notation.',answer:'1.005e5',isText:true,solution:'Move decimal 5 places left: 100,500 → 1.00500 × 10^5. All digits of the coefficient (1, 0, 0, 5) are significant (captive zeros). Written as 1.005 × 10^5 (4 sig figs shown).'},

  // ── MORE CALC — Factor-Label / Unit Conversions ──
  {id:'p65',difficulty:'easy',type:'calc',tag:'Calculation',q:'Convert 0.450 kg to grams.',answer:'450',tolerance:0.5,solution:'0.450 kg × (1000 g / 1 kg) = 450 g. Three sig figs retained.'},
  {id:'p66',difficulty:'easy',type:'calc',tag:'Calculation',q:'Convert 5800 mL to liters.',answer:'5.80',tolerance:0.005,solution:'5800 mL × (1 L / 1000 mL) = 5.80 L. (Assuming 3 sig figs in 5800 as written — if ambiguous, express as 5.80 × 10^0 L.)'},
  {id:'p67',difficulty:'easy',type:'calc',tag:'Calculation',q:'Convert 100.°C (boiling point of water) to Kelvin.',answer:'373',tolerance:1,solution:'K = °C + 273 = 100 + 273 = 373 K'},
  {id:'p68',difficulty:'easy',type:'calc',tag:'Calculation',q:'Convert 310 K (approximate body temperature) to °C.',answer:'37',tolerance:1,solution:'°C = K - 273 = 310 - 273 = 37°C'},
  {id:'p69',difficulty:'medium',type:'calc',tag:'Calculation',q:'Convert 3.25 hours to seconds.',answer:'11700',tolerance:10,solution:'3.25 hr × (60 min/hr) × (60 s/min) = 3.25 × 3600 = 11,700 s = 1.17 × 10^4 s (3 sig figs)'},

  // ── MORE MULTI — Sig Figs Calculations ──
  {id:'p70',difficulty:'medium',type:'multi',tag:'Multi-step',q:'Calculate: (12.50 g - 2.3 g). Apply the correct sig fig rule.',answer:'10.2',tolerance:0.05,solution:'Subtraction: fewest decimal places. 12.50 has 2 dp; 2.3 has 1 dp. Calculate: 12.50 - 2.3 = 10.20 → round to 1 dp → 10.2 g'},
  {id:'p71',difficulty:'medium',type:'multi',tag:'Multi-step',q:'Calculate: 4.25 cm × 2.0 cm × 8.00 cm. Apply the correct sig fig rule.',answer:'68',tolerance:1,solution:'Multiplication: fewest sig figs. 4.25 (3 sf) × 2.0 (2 sf) × 8.00 (3 sf) → limited by 2.0 → 2 sig figs. 4.25 × 2.0 × 8.00 = 68.0 → 68 cm^3'},
  {id:'p72',difficulty:'medium',type:'multi',tag:'Multi-step',q:'A student measures 150.0 mL of solution and transfers it to a beaker. They accidentally spill some; 132 mL remains. How much spilled? Report with correct sig figs.',answer:'18',tolerance:0.5,solution:'150.0 - 132 = 18.0 mL. Subtraction rule: fewest decimal places. 132 has 0 dp; 150.0 has 1 dp → round to 0 dp → 18 mL (2 sig figs)'},
  {id:'p73',difficulty:'medium',type:'multi',tag:'Density & Error',q:'Calculate percent error: experimental = 2.35 g/mL, accepted = 2.70 g/mL.',answer:'13.0',tolerance:0.2,solution:'% error = |2.35 - 2.70| / 2.70 × 100% = 0.35/2.70 × 100% = 12.96% → 13.0%'},
  {id:'p74',difficulty:'medium',type:'multi',tag:'Multi-step',q:'A rectangular metal block measures 4.0 cm × 3.0 cm × 2.0 cm and has a mass of 192 g. What is its density in g/cm^3?',answer:'8.0',tolerance:0.1,solution:'V = 4.0 × 3.0 × 2.0 = 24 cm^3 (2 sig figs). D = m/V = 192/24 = 8.0 g/cm^3. This density matches copper (8.96) approximately — likely nickel or a copper alloy.'},

  // ── MORE CONCEPT — Chemistry Branches & Matter ──
  {id:'p75',difficulty:'medium',type:'concept',tag:'Properties of Matter',q:'A student observes that a silver coin tarnishes over time. This change is:',choices:['A physical change — the silver is still silver underneath.','A chemical change — new substances form when silver reacts with sulfur compounds in air.','Not a chemical or physical change — tarnish is just dirt.','A nuclear change — silver atoms are converting to a different element.'],correct:1,solution:'Tarnishing is a chemical change: silver reacts with hydrogen sulfide (H2S) in air to form silver sulfide (Ag2S), a new substance with different properties. Physical changes (bending, melting) do not produce new substances.'},

  {id:'p76',difficulty:'medium',type:'concept',tag:'Properties of Matter',q:'A chemist evaporates a salt-water solution and collects the solid salt left behind. This is best described as:',choices:['A chemical change, because the water disappeared.','A physical change — the water and salt were separated but neither changed identity.','A nuclear change — the salt converted to a different compound.','A chemical change — salt cannot exist without water.'],correct:1,solution:'Evaporation is a physical change — water changes state (liquid → gas) and the salt is physically separated, but no new chemical substances are created. Both water and NaCl retain their chemical identities throughout.'},

  {id:'p77',difficulty:'easy',type:'concept',tag:'Properties of Matter',q:'Which of the following is a pure substance?',choices:['Air','Salt water','Distilled water','Granite'],correct:2,solution:'Distilled water (H2O) is a pure substance — it has a fixed composition and definite properties. Air is a mixture of gases. Salt water is a mixture of NaCl and H2O. Granite is a mixture of minerals (quartz, feldspar, mica).'},

  {id:'p78',difficulty:'medium',type:'concept',tag:'Properties of Matter',q:'Which of the following is a physical property of copper?',choices:['Copper reacts with oxygen to form copper oxide.','Copper conducts electricity.','Copper corrodes in acidic solutions.','Copper oxidizes when heated strongly.'],correct:1,solution:'A physical property is observed or measured without changing the substance\'s identity. Electrical conductivity, color, melting point, and density are all physical properties. Reacting with oxygen or acid is a chemical property — it describes how copper changes into a different substance.'},

  {id:'p79',difficulty:'easy',type:'concept',tag:'Concept',q:'What is the difference between accuracy and precision?',choices:['Accuracy refers to getting the same result every time; precision means being close to the true value.','Accuracy means being close to the true value; precision means getting consistent, repeatable results.','They are synonyms — both mean getting the correct answer.','Accuracy applies to mass measurements; precision applies to volume measurements.'],correct:1,solution:'Accuracy = closeness to the true or accepted value. Precision = reproducibility — how close repeated measurements are to each other. A precise measurement is not necessarily accurate (systematic error can shift all readings in one direction). Good science requires both.'},

  // ── 5 additional problems to reach 84 ──
  {id:'p80',difficulty:'easy',type:'calc',tag:'Calculation',q:'Convert 55.0 mg to grams.',answer:'0.0550',tolerance:0.0005,solution:'55.0 mg × (1 g / 1000 mg) = 0.0550 g. Three sig figs. The trailing zero is significant.'},
  {id:'p81',difficulty:'easy',type:'calc',tag:'Calculation',q:'Convert 2.00 km to meters.',answer:'2000',tolerance:0.5,solution:'2.00 km × (1000 m / 1 km) = 2000 m = 2.00 × 10^3 m (3 sig figs)'},
  {id:'p82',difficulty:'medium',type:'concept',tag:'Concept',q:'How many significant figures are in the measurement 0.007090 g?',choices:['2','3','4','7'],correct:2,solution:'Leading zeros (0.00) are not significant — placeholders only. Significant digits: 7, 0 (captive, between 7 and 9), 9, 0 (trailing zero after decimal) → 4 sig figs.'},
  {id:'p83',difficulty:'medium',type:'multi',tag:'Density & Error',q:'A student reports their density result as 8.93 g/cm^3. The accepted value for copper is 8.96 g/cm^3. Calculate the percent error.',answer:'0.335',tolerance:0.05,solution:'% error = |8.93 - 8.96| / 8.96 × 100% = 0.03/8.96 × 100% = 0.335%. Less than 1% — excellent precision for a lab measurement.'},
  {id:'p84',difficulty:'easy',type:'concept',tag:'Properties of Matter',q:'Which of the following best describes a mixture?',choices:['A substance with a fixed chemical formula and definite properties.','Two or more pure substances physically combined, each retaining its own properties.','A substance formed when two elements bond chemically.','Any liquid that contains dissolved solids.'],correct:1,solution:'A mixture contains two or more substances physically combined — they retain their individual properties and can be separated by physical means (filtering, evaporation, distillation). Salt water is a mixture; NaCl itself is a pure substance (compound).'},

  // GRADUATED CYLINDER READING — SVG (6 problems)
  {id:'p85',difficulty:'medium',type:'concept',tag:'Graduated Cylinder',q:`What volume is shown in this graduated cylinder? Read from the bottom of the meniscus at eye level.<br>${renderTallCylinderSvg(259.4, 268.4)}`,choices:['21.0 mL','23.0 mL','25.0 mL','27.0 mL'],correct:1,solution:'The meniscus bottom (red dashed line) sits at the 23 mL mark. Each minor division = 2 mL. Always read from eye level at the bottom of the concave curve. Answer: 23.0 mL'},
  {id:'p86',difficulty:'medium',type:'concept',tag:'Graduated Cylinder',q:`What volume is shown in this graduated cylinder?<br>${renderTallCylinderSvg(221.0, 230.0)}`,choices:['33.0 mL','35.0 mL','37.0 mL','39.0 mL'],correct:1,solution:'The meniscus bottom aligns with the 35 mL mark, midway between the 30 label and the unlabeled tick above it. Minor ticks are every 2 mL. Answer: 35.0 mL'},
  {id:'p87',difficulty:'medium',type:'concept',tag:'Graduated Cylinder',q:`What volume is shown in this graduated cylinder?<br>${renderTallCylinderSvg(182.6, 191.6)}`,choices:['45.0 mL','47.0 mL','49.0 mL','51.0 mL'],correct:1,solution:'The meniscus bottom sits at 47 mL — one minor division below the unlabeled 48 mark (or three ticks below 50, counting 49, 47). Always estimate one digit past the smallest division. Answer: 47.0 mL'},
  {id:'p88',difficulty:'medium',type:'concept',tag:'Graduated Cylinder',q:`What volume is shown in this graduated cylinder?<br>${renderTallCylinderSvg(134.6, 143.6)}`,choices:['60.0 mL','62.0 mL','64.0 mL','66.0 mL'],correct:1,solution:'The meniscus bottom falls at 62 mL — one minor division above the unlabeled 60 mark. The 50 and 70 labeled ticks bracket this region. Answer: 62.0 mL'},
  {id:'p89',difficulty:'hard',type:'concept',tag:'Graduated Cylinder',q:`What volume is shown in this graduated cylinder?<br>${renderTallCylinderSvg(89.8, 98.8)}`,choices:['72.0 mL','74.0 mL','76.0 mL','78.0 mL'],correct:2,solution:'The meniscus bottom sits three ticks above the 70 mL label (70 → 72 → 74 → 76). Each tick = 2 mL. Answer: 76.0 mL'},
  {id:'p90',difficulty:'hard',type:'concept',tag:'Graduated Cylinder',q:`What volume is shown in this graduated cylinder?<br>${renderTallCylinderSvg(64.2, 73.2)}`,choices:['80.0 mL','82.0 mL','84.0 mL','86.0 mL'],correct:2,solution:'Counting down from 90: 88, 86, 84. The meniscus bottom falls at the third minor tick below 90. Answer: 84.0 mL'},

  // ELECTRONIC BALANCE READING — SVG (4 problems)
  {id:'p91',difficulty:'easy',type:'concept',tag:'Balance Reading',q:`An electronic balance displays the reading below. How many significant figures are in this measurement?<br>${renderBalanceSvg('12.457')}`,choices:['3','4','5','6'],correct:2,solution:'The display shows 12.457 g. All five digits are significant (nonzero or captive). Electronic balances display every sig fig — no estimation needed. Answer: 5 sig figs.'},
  {id:'p92',difficulty:'medium',type:'concept',tag:'Balance Reading',q:`The balance shows the reading below. A student records "8.3 g" in their notebook. What sig fig error did they make?<br>${renderBalanceSvg('8.300')}`,choices:['No error — 8.3 and 8.300 are the same measurement.','The student dropped two significant figures; the correct recording is 8.300 g.','8.3 g is more precise because fewer digits means less chance of error.','The balance is displaying extra digits that do not matter.'],correct:1,solution:'The display shows 8.300 g — 4 significant figures. Writing 8.3 reduces this to 2 sig figs. Those trailing zeros tell you the measurement was made to the nearest 0.001 g. Always record exactly what the instrument displays.'},
  {id:'p93',difficulty:'medium',type:'calc',tag:'Balance Reading',q:`The balance shows this mass. A student adds a 55.0 g standard weight to the same pan. What is the total mass? Apply the addition sig fig rule.<br>${renderBalanceSvg('145.62')}`,answer:'200.6',tolerance:0.1,solution:'Balance reads 145.62 g (2 decimal places). Added weight: 55.0 g (1 decimal place). Sum = 200.62 g → round to 1 decimal place = 200.6 g. Addition rule: limit to fewest decimal places.'},
  {id:'p94',difficulty:'easy',type:'concept',tag:'Balance Reading',q:`The balance below shows a reading. What does this tell you about the sample?<br>${renderBalanceSvg('0.085')}`,choices:['Nothing unusual — all balances read this way.','The mass is less than 1 g, indicating a very small or lightweight sample.','The balance is malfunctioning because readings below 1 are impossible.','The leading zero before the decimal is a significant figure.'],correct:1,solution:'The display reads 0.085 g = 85 mg — a very small mass (about the mass of a few grains of salt). The leading zero is NOT significant. Only the 8 and 5 are sig figs (2 total). Electronic analytical balances can measure to 0.001 g precision.'},

  // SIG FIGS — EXPANDED (8 problems)
  {id:'p95',difficulty:'medium',type:'concept',tag:'Concept',q:'How many significant figures does 100.0 contain?',choices:['1','2','3','4'],correct:3,solution:'100.0 has 4 sig figs: 1 (nonzero), 0 (trailing), 0 (trailing), 0 (trailing after decimal). Because the decimal point is present, all trailing zeros shown are significant.'},
  {id:'p96',difficulty:'medium',type:'concept',tag:'Concept',q:'How many significant figures does 0.0900 contain?',choices:['1','2','3','4'],correct:2,solution:'Leading zeros (0.0) are not significant — they are just placeholders. The significant digits are: 9 (nonzero), 0 (trailing after decimal, after nonzero), 0 (same rule). Total: 3 sig figs.'},
  {id:'p97',difficulty:'medium',type:'concept',tag:'Concept',q:'A student calculates 12.52 + 1.7 + 3.016. What is the correctly rounded sum?',choices:['17.2','17.24','17.236','17.3'],correct:0,solution:'Addition rule: fewest decimal places. 12.52 (2 dp), 1.7 (1 dp — limits the answer), 3.016 (3 dp). Sum = 17.236 → round to 1 decimal place → 17.2'},
  {id:'p98',difficulty:'medium',type:'concept',tag:'Calculations/Scientific Notation',q:'(6.4 × 10^3) × (2.50 × 10^2) — how many sig figs should the answer have?',choices:['1','2','3','4'],correct:1,solution:'Multiplication: fewest sig figs. 6.4 × 10^3 has 2 sig figs; 2.50 × 10^2 has 3 sig figs. Answer limited to 2 sig figs: 6.4 × 2.50 = 16.0; 10^3 × 10^2 = 10^5; final answer = 1.6 × 10^6 (2 sig figs).'},
  {id:'p99',difficulty:'medium',type:'multi',tag:'Multi-step',q:'A student measures: length = 8.24 cm, width = 3.1 cm. Calculate the area. Enter only the number.',answer:'26',tolerance:0.5,solution:'Area = 8.24 × 3.1 = 25.544 cm^2. Fewest sig figs: 8.24 has 3, 3.1 has 2. Round to 2 sig figs: 26 cm^2.'},
  {id:'p100',difficulty:'medium',type:'concept',tag:'Concept',q:'A student writes: "The mass is approximately 50 grams." What is the minimum unambiguous way to record this measurement with 2 sig figs?',choices:['"50 g"','"50. g" or "5.0 × 10^1 g"','"050 g"','"50.00 g"'],correct:1,solution:'"50" is ambiguous (1 or 2 sig figs). Adding a decimal point — "50." — signals exactly 2 sig figs. Scientific notation "5.0 × 10^1" is equally clear. "50.00" would indicate 4 sig figs, which overclaims precision.'},
  {id:'p101',difficulty:'medium',type:'multi',tag:'Density & Error',q:'A piece of metal: volume = 4.5 cm^3, mass = 38.52 g. Calculate density to correct sig figs.',answer:'8.6',tolerance:0.1,solution:'D = 38.52 / 4.5 = 8.56 g/cm^3. Fewest sig figs: 38.52 has 4, 4.5 has 2. Round to 2 sig figs: 8.6 g/cm^3.'},
  {id:'p102',difficulty:'medium',type:'concept',tag:'Concept',q:'Which is the correctly rounded result of 88.5 ÷ 3.00?',choices:['29','29.5','29.50','30'],correct:1,solution:'88.5 has 3 sig figs; 3.00 has 3 sig figs. Answer should have 3 sig figs. 88.5 / 3.00 = 29.5. This already has 3 sig figs. 29.50 would claim 4 sig figs — overclaiming.'},

  // SCIENTIFIC NOTATION — OPERATIONS (5 problems)
  {id:'p103',difficulty:'medium',type:'multi',tag:'Calculations/Scientific Notation',q:'(3.0 × 10^4) × (2.0 × 10^3) = ? Enter in scientific notation, e.g. 6.0e7.',answer:'6.0e7',isText:true,solution:'Multiply coefficients: 3.0 × 2.0 = 6.0. Add exponents: 4 + 3 = 7. Answer: 6.0 × 10^7'},
  {id:'p104',difficulty:'medium',type:'multi',tag:'Calculations/Scientific Notation',q:'(8.4 × 10^6) ÷ (2.0 × 10^2) = ? Enter in scientific notation, e.g. 4.2e4.',answer:'4.2e4',isText:true,solution:'Divide coefficients: 8.4 ÷ 2.0 = 4.2. Subtract exponents: 6 - 2 = 4. Answer: 4.2 × 10^4'},
  {id:'p105',difficulty:'medium',type:'calc',tag:'Calculations/Scientific Notation',q:'Express in proper scientific notation: 52.4 × 10^3',answer:'5.24e4',isText:true,solution:'The coefficient 52.4 is not between 1 and 10. Move decimal left 1 place: 5.24; add 1 to exponent: 10^3 → 10^4. Answer: 5.24 × 10^4'},
  {id:'p106',difficulty:'hard',type:'calc',tag:'Calculations/Scientific Notation',q:'Express 0.0035 × 10^-2 in proper scientific notation.',answer:'3.5e-5',isText:true,solution:'Convert 0.0035 = 3.5 × 10^-3. Then × 10^-2: exponents add: -3 + (-2) = -5. Answer: 3.5 × 10^-5'},
  {id:'p107',difficulty:'medium',type:'concept',tag:'Calculations/Scientific Notation',q:'(4.5 × 10^-3) + (3.2 × 10^-3) = ?',choices:['7.7 × 10^-6','7.7 × 10^-3','7.7 × 10^0','1.44 × 10^-5'],correct:1,solution:'Addition with matching exponents: add the coefficients. 4.5 + 3.2 = 7.7; keep the shared exponent -3. Answer: 7.7 × 10^-3. (Do not add exponents — that is for multiplication only.)'},

  // FACTOR-LABEL — HARDER (6 problems)
  {id:'p108',difficulty:'hard',type:'multi',tag:'Multi-step',q:'Convert 55 miles per hour to meters per second. (1 mile = 1609 m; 1 hr = 3600 s)',answer:'24.6',tolerance:0.3,solution:'55 mi/hr × (1609 m/mi) × (1 hr/3600 s) = 55 × 1609 / 3600 = 24.58 m/s → 24.6 m/s (3 sig figs)'},
  {id:'p109',difficulty:'hard',type:'multi',tag:'Multi-step',q:'A patient receives 250 mg of medication per dose, 3 doses per day, for 10 days. What is the total medication in grams?',answer:'7.50',tolerance:0.05,solution:'250 mg/dose × 3 doses/day × 10 days = 7500 mg. Convert: 7500 mg × (1 g / 1000 mg) = 7.50 g'},
  {id:'p110',difficulty:'medium',type:'calc',tag:'Calculation',q:'Convert 2.50 × 10^3 mg to kg.',answer:'0.00250',tolerance:0.00001,solution:'2500 mg × (1 g / 1000 mg) × (1 kg / 1000 g) = 2.50 × 10^-3 kg = 0.00250 kg'},
  {id:'p111',difficulty:'medium',type:'multi',tag:'Multi-step',q:'A marathon is 26.2 miles. How many meters is that? (1 mile = 1609 m)',answer:'42200',tolerance:100,solution:'26.2 mi × (1609 m/mi) = 42,155.8 m → 42,200 m = 4.22 × 10^4 m (3 sig figs)'},
  {id:'p112',difficulty:'medium',type:'calc',tag:'Calculation',q:'Convert 1.00 atm to pascals. (1 atm = 101,325 Pa) Enter in scientific notation.',answer:'1.01e5',isText:true,solution:'1.00 atm × (101,325 Pa/atm) = 101,325 Pa = 1.01325 × 10^5 Pa → 1.01 × 10^5 Pa (3 sig figs)'},
  {id:'p113',difficulty:'easy',type:'multi',tag:'Multi-step',q:'A 150 lb person — what is their mass in kg? (1 kg = 2.205 lb)',answer:'68.0',tolerance:0.5,solution:'150 lb × (1 kg / 2.205 lb) = 68.03 kg → 68.0 kg (3 sig figs)'},

  // DENSITY / PERCENT ERROR — EXPANDED (4 problems)
  {id:'p114',difficulty:'medium',type:'multi',tag:'Density & Error',q:'A student measures the density of aluminum as 2.58 g/mL. Accepted value: 2.70 g/mL. Calculate percent error.',answer:'4.4',tolerance:0.2,solution:'% error = |2.58 - 2.70| / 2.70 × 100% = 0.12 / 2.70 × 100% = 4.44% → 4.4%'},
  {id:'p115',difficulty:'medium',type:'multi',tag:'Density & Error',q:'A liquid (mass = 34.6 g) is added to a cylinder reading 15.0 mL; the new reading is 46.0 mL. Calculate the density.',answer:'1.12',tolerance:0.02,solution:'Volume = 46.0 - 15.0 = 31.0 mL. D = 34.6 g / 31.0 mL = 1.116 → 1.12 g/mL (3 sig figs)'},
  {id:'p116',difficulty:'medium',type:'concept',tag:'Concept',q:'Two students measure the same object: Student A records 5.1 g/mL; Student B records 5.11 g/mL. Which statement is true?',choices:['Student A is more accurate.','Student B recorded more sig figs and their measurement is more precise.','Both are equally precise — they measured the same object.','Student A must have made an error.'],correct:1,solution:'Precision = number of sig figs / decimal places recorded. Student B has 3 sig figs (hundredths place); Student A has 2 (tenths place). Neither can be judged more accurate without knowing the true value. More sig figs = more precision, not necessarily more accuracy.'},
  {id:'p117',difficulty:'easy',type:'multi',tag:'Density & Error',q:'What is the volume of an object with mass 63.5 g and density 8.92 g/cm^3?',answer:'7.12',tolerance:0.05,solution:'V = m / D = 63.5 / 8.92 = 7.118 cm^3 → 7.12 cm^3 (3 sig figs)'},

  // LAB SAFETY / GHS — EXPANDED (5 problems)
  {id:'p118',difficulty:'easy',type:'concept',tag:'Safety/GHS',q:'The GHS flame-over-circle symbol on a chemical label indicates:',choices:['Acutely toxic — lethal in small amounts','Flammable — ignites easily near heat or sparks','Oxidizer — can intensify fire by supplying oxygen','Hazardous to the aquatic environment'],correct:2,solution:'GHS03 (flame over circle) indicates an oxidizer. Oxidizers are not necessarily combustible themselves, but they can make other materials burn more intensely. Keep them away from fuels, organics, and ignition sources.'},
  {id:'p119',difficulty:'easy',type:'concept',tag:'Safety/GHS',q:'The correct procedure when heating a liquid in a test tube is:',choices:['Point the open end toward yourself to monitor for boiling.','Hold the tube with fingers to feel temperature changes.','Clamp the tube and angle the open end away from all people.','Seal the open end with your thumb to prevent spills.'],correct:2,solution:'Liquids can superheat and eject suddenly ("bumping"). Always clamp the tube and angle it toward open space. Never seal a heated tube or point it at anyone.'},
  {id:'p120',difficulty:'easy',type:'concept',tag:'Safety/GHS',q:'A glass thermometer breaks during a lab. The correct procedure is:',choices:['Pick up pieces by hand and dispose in regular trash.','Sweep with a dry brush into a dustpan; regular trash is fine.','Use tongs or cardboard to collect shards; dispose in the broken glass container.','Leave it and notify the teacher at the end of class.'],correct:2,solution:'Broken glass is a sharps hazard. Never use bare hands. Use cardboard or a brush and dustpan. Dispose in the dedicated sharps/broken glass container — not regular trash, which can injure custodians.'},
  {id:'p121',difficulty:'easy',type:'concept',tag:'Safety/GHS',q:'A student is working with a flammable solvent while a Bunsen burner is lit. They should:',choices:['Work quickly to minimize time the solvent is open near the flame.','Extinguish the burner completely before opening any flammable solvent.','Keep the solvent on the far side of the bench from the burner.','Open the solvent only when the flame is at its lowest setting.'],correct:1,solution:'Flammable vapors are heavier than air and travel across bench surfaces to reach flames. The only safe practice is a completely extinguished burner. There is no safe distance — vapors diffuse unpredictably.'},
  {id:'p122',difficulty:'easy',type:'concept',tag:'Safety/GHS',q:'After lab, a student removes gloves but notices an unusual smell on their hands. They should:',choices:['Ignore it — gloves tested negative so hands are safe.','Rinse hands with the nearest liquid available.','Wash hands thoroughly with soap and water for at least 20 seconds.','Apply hand sanitizer and proceed.'],correct:2,solution:'Always wash hands with soap and water after any lab work. Gloves can have micro-tears and may not fully protect. Hand sanitizer does not remove chemical residues. Soap and water is the standard post-lab procedure before leaving the lab.'},

  // CHEMISTRY BRANCHES / MEASUREMENT CONCEPTS (3 problems)
  {id:'p123',difficulty:'easy',type:'concept',tag:'Concept',q:'A forensic chemist analyzes a trace substance at a crime scene to identify an unknown compound. Which branch of chemistry does this primarily represent?',choices:['Organic chemistry','Biochemistry','Analytical chemistry','Physical chemistry'],correct:2,solution:'Analytical chemistry identifies and quantifies substances. Forensic identification of unknowns is a direct application. The goal is "what is it and how much is there?" — the defining questions of analytical chemistry.'},
  {id:'p124',difficulty:'easy',type:'concept',tag:'Concept',q:'Which correctly distinguishes accuracy from precision?',choices:['Accuracy = number of decimal places; precision = closeness to true value.','Accuracy = closeness to the true value; precision = reproducibility of repeated measurements.','Accuracy and precision are synonyms in scientific writing.','Precision = closeness to true value; accuracy = number of sig figs.'],correct:1,solution:'Accuracy: how close to the accepted/true value. Precision: how reproducible repeated measurements are. A precise but inaccurate result has all readings clustered together, but far from the true value — a sign of systematic error.'},
  {id:'p125',difficulty:'medium',type:'concept',tag:'Concept',q:'A thermometer consistently reads 2°C too high every trial. This is an example of:',choices:['Random error — the amount varies each trial.','Systematic error — a consistent offset caused by instrument calibration.','Human error that cannot be quantified or corrected.','Precision error from too few significant figures.'],correct:1,solution:'Systematic error shifts all measurements the same direction by the same amount. Here: +2°C every time. Unlike random error, averaging more trials does NOT reduce systematic error. The fix is instrument recalibration or applying a correction factor.'},

  // ═══════════════════════════════════════════════════════
  // EXPANSION BATCH — 60 problems added to reach 185 total
  // Difficulty-tagged: 20 easy | 25 medium | 15 hard
  // ═══════════════════════════════════════════════════════

  // ── EASY (20) — single-step conversions & direct recall ──
  {id:'p126',difficulty:'easy',type:'calc',tag:'Calculation',q:'Convert 950 mL to liters.',answer:'0.950',tolerance:0.005,solution:'950 mL × (1 L / 1000 mL) = 0.950 L'},
  {id:'p127',difficulty:'easy',type:'calc',tag:'Calculation',q:'Convert 6.2 kg to grams.',answer:'6200',tolerance:10,solution:'6.2 kg × (1000 g / 1 kg) = 6200 g'},
  {id:'p128',difficulty:'easy',type:'calc',tag:'Calculation',q:'Convert 275 mg to grams.',answer:'0.275',tolerance:0.002,solution:'275 mg × (1 g / 1000 mg) = 0.275 g'},
  {id:'p129',difficulty:'easy',type:'calc',tag:'Calculation',q:'Convert 3.8 L to milliliters.',answer:'3800',tolerance:10,solution:'3.8 L × (1000 mL / 1 L) = 3800 mL'},
  {id:'p130',difficulty:'easy',type:'calc',tag:'Calculation',q:'Convert 42°C to Kelvin. (K = °C + 273)',answer:'315',tolerance:1,solution:'K = 42 + 273 = 315 K'},
  {id:'p131',difficulty:'easy',type:'calc',tag:'Calculation',q:'Convert 350 K to °C. (°C = K − 273)',answer:'77',tolerance:1,solution:'°C = 350 − 273 = 77°C'},
  {id:'p132',difficulty:'easy',type:'calc',tag:'Calculation',q:'Convert 68°F to °C. (°C = (°F − 32) × 5/9)',answer:'20',tolerance:0.5,solution:'°C = (68 − 32) × 5/9 = 36 × 0.5556 = 20°C'},
  {id:'p133',difficulty:'easy',type:'calc',tag:'Calculation',q:'Convert 15°C to °F. (°F = °C × 9/5 + 32)',answer:'59',tolerance:0.5,solution:'°F = (15 × 1.8) + 32 = 27 + 32 = 59°F'},
  {id:'p134',difficulty:'easy',type:'concept',tag:'Concept',q:'Which piece of glassware is best for holding and swirling a reacting solution, but NOT for precise volume measurement?',choices:['Volumetric pipette','Graduated cylinder','Erlenmeyer flask','Burette'],correct:2,solution:'Erlenmeyer flasks are shaped for safe mixing, swirling, and heating — their volume markings are only approximate (±5–10%). Use a graduated cylinder, pipette, or burette when the volume itself matters.'},
  {id:'p135',difficulty:'easy',type:'concept',tag:'Safety/GHS',q:'The GHS corrosion symbol (test tubes pouring onto a hand and a surface) indicates the substance:',choices:['Is flammable near open flames','Destroys living tissue and corrodes metals','Is an oxidizer that intensifies fire','Is toxic only if inhaled'],correct:1,solution:'GHS05 (corrosion symbol) marks substances that cause severe skin burns, eye damage, and can corrode metals on contact. Strong acids and bases carry this label.'},
  {id:'p136',difficulty:'easy',type:'concept',tag:'Safety/GHS',q:'Before beginning any lab procedure, a student should first:',choices:['Read the entire procedure and locate the safety equipment','Put on gloves and start immediately','Begin heating reagents to save time','Ask a classmate what to do'],correct:0,solution:'Reading the full procedure first prevents mistakes from missing a later step, and knowing where the eyewash, shower, and fire extinguisher are located means you can react instantly if something goes wrong.'},
  {id:'p137',difficulty:'easy',type:'concept',tag:'Properties of Matter',q:'Which of the following is an element, not a compound?',choices:['Oxygen gas (O2)','Water (H2O)','Table salt (NaCl)','Carbon dioxide (CO2)'],correct:0,solution:'O2 is made of only one type of atom (oxygen) bonded together, so it is an element. Water, table salt, and carbon dioxide are each made of two or more different elements chemically combined, making them compounds.'},
  {id:'p138',difficulty:'easy',type:'concept',tag:'Properties of Matter',q:'A compound is best defined as:',choices:['Two or more elements chemically combined in a fixed ratio','Any mixture of two substances','A pure form of a single element','Any substance that conducts electricity'],correct:0,solution:'Compounds form when two or more elements bond chemically in a fixed, definite ratio (e.g., H2O is always 2 hydrogen to 1 oxygen). This distinguishes compounds from mixtures, which can combine in any ratio.'},
  {id:'p139',difficulty:'easy',type:'calc',tag:'Calculation',q:'Convert 8.0 mm to centimeters.',answer:'0.80',tolerance:0.02,solution:'8.0 mm × (1 cm / 10 mm) = 0.80 cm'},
  {id:'p140',difficulty:'easy',type:'calc',tag:'Calculation',q:'Convert 0.65 m to centimeters.',answer:'65',tolerance:1,solution:'0.65 m × (100 cm / 1 m) = 65 cm'},
  {id:'p141',difficulty:'easy',type:'concept',tag:'Properties of Matter',q:'Muddy river water, which contains visible suspended particles, is best classified as:',choices:['A heterogeneous mixture','A homogeneous mixture','A pure substance','A compound'],correct:0,solution:'A heterogeneous mixture has visibly different regions or particles — you can see the mud is not uniformly distributed. A homogeneous mixture (like salt water) looks the same throughout.'},
  {id:'p142',difficulty:'easy',type:'concept',tag:'Properties of Matter',q:'Salt fully dissolved in water forms a solution, which is classified as:',choices:['A heterogeneous mixture','A homogeneous mixture','An element','A pure compound'],correct:1,solution:'Once dissolved, salt is uniformly distributed throughout the water — you cannot see individual salt particles or distinguish regions. Uniform composition throughout defines a homogeneous mixture.'},
  {id:'p143',difficulty:'easy',type:'concept',tag:'Safety/GHS',q:'Which action is a safety violation in the chemistry lab?',choices:['Wearing safety goggles the entire time','Eating a snack at your lab bench','Reading the procedure before starting','Tying back loose hair'],correct:1,solution:'Food and drink are never allowed in a lab — chemical residue on bench surfaces, glassware, or your hands can contaminate food and cause accidental ingestion of hazardous substances.'},
  {id:'p144',difficulty:'easy',type:'concept',tag:'Concept',q:'What is the freezing point of pure water at standard atmospheric pressure, in Kelvin?',choices:['0 K','100 K','273 K','373 K'],correct:2,solution:'Water freezes at 0°C, and K = °C + 273, so 0°C = 273 K. Water boils at 100°C = 373 K.'},
  {id:'p145',difficulty:'easy',type:'concept',tag:'Concept',q:'At standard atmospheric pressure, water boils at:',choices:['0°C','100°C','212°C','273°C'],correct:1,solution:'Water boils at 100°C (equivalent to 212°F or 373 K) at standard atmospheric pressure (1 atm).'},

  // ── MEDIUM (25) — two-rule combinations, sig figs, sci notation, applied concepts ──
  {id:'p146',difficulty:'medium',type:'calc',tag:'Calculation',q:'Convert 2.35 × 10^4 mg to kilograms.',answer:'0.0235',tolerance:0.0002,solution:'2.35 × 10^4 mg = 23,500 mg. Convert mg → g → kg: 23,500 mg × (1 g/1000 mg) × (1 kg/1000 g) = 0.0235 kg'},
  {id:'p147',difficulty:'medium',type:'calc',tag:'Calculation',q:'Convert 0.048 km to centimeters.',answer:'4800',tolerance:50,solution:'0.048 km × (1000 m/km) = 48 m. Then 48 m × (100 cm/m) = 4800 cm = 4.8 × 10^3 cm.'},
  {id:'p148',difficulty:'medium',type:'multi',tag:'Multi-step',q:'Convert 6.00 ft to centimeters. (1 ft = 30.48 cm)',answer:'183',tolerance:1,solution:'6.00 ft × (30.48 cm/ft) = 182.88 cm → 183 cm (3 sig figs, matching 6.00 ft).'},
  {id:'p149',difficulty:'medium',type:'multi',tag:'Multi-step',q:'Calculate 45.60 − 12.3, applying the correct sig fig rule.',answer:'33.3',tolerance:0.05,solution:'Subtraction: fewest decimal places wins. 45.60 (2 dp) − 12.3 (1 dp) = 33.30 → round to 1 dp → 33.3'},
  {id:'p150',difficulty:'medium',type:'multi',tag:'Multi-step',q:'Calculate 5.02 × 1.4, applying the correct sig fig rule.',answer:'7.0',tolerance:0.1,solution:'Multiplication: fewest sig figs wins. 5.02 (3 sf) × 1.4 (2 sf) = 7.028 → round to 2 sig figs → 7.0'},
  {id:'p151',difficulty:'medium',type:'concept',tag:'Concept',q:'How many significant figures does 3.00 × 10^2 contain?',choices:['1','2','3','4'],correct:2,solution:'In scientific notation, every digit in the coefficient is significant. 3.00 has three digits (3, 0, 0) — all significant, giving 3 sig figs total.'},
  {id:'p152',difficulty:'medium',type:'concept',tag:'Concept',q:'How many significant figures does the number 6000 (written with no decimal point) have, by standard convention?',choices:['1','2','3','4'],correct:0,solution:'Without a decimal point, trailing zeros in a whole number are ambiguous and, by convention, are not counted as significant. 6000 is treated as having 1 sig fig unless written as 6.000 × 10^3 or with an explicit decimal.'},
  {id:'p153',difficulty:'medium',type:'concept',tag:'Concept',q:'If a student\'s experimental value is higher than the accepted value, the percent error is:',choices:['Always negative','Always reported as positive, using absolute value','Always zero','Impossible to calculate'],correct:1,solution:'The percent error formula uses absolute value: |experimental − accepted| / accepted × 100%. This keeps percent error a positive number regardless of whether the experimental value was too high or too low.'},
  {id:'p154',difficulty:'medium',type:'multi',tag:'Density & Error',q:'A student measures 15.8 mL for a liquid; the accepted volume is 16.5 mL. Calculate the percent error.',answer:'4.24',tolerance:0.1,solution:'% error = |15.8 − 16.5| / 16.5 × 100% = 0.7 / 16.5 × 100% = 4.24%'},
  {id:'p155',difficulty:'medium',type:'multi',tag:'Density & Error',q:'A sample has mass 54.0 g and volume 20.0 mL. Calculate its density in g/mL.',answer:'2.70',tolerance:0.02,solution:'D = m/V = 54.0 / 20.0 = 2.70 g/mL (3 sig figs)'},
  {id:'p156',difficulty:'medium',type:'multi',tag:'Density & Error',q:'A liquid (mass = 41.6 g) is added to a graduated cylinder reading 25.0 mL; the level rises to 33.0 mL. Calculate the density.',answer:'5.2',tolerance:0.1,solution:'Volume = 33.0 − 25.0 = 8.0 mL (2 sig figs). D = 41.6 / 8.0 = 5.2 g/mL — limited to 2 sig figs by the volume measurement.'},
  {id:'p157',difficulty:'medium',type:'calc',tag:'Calculations/Scientific Notation',q:'Express 0.000098 in scientific notation.',answer:'9.8e-5',isText:true,solution:'Move the decimal 5 places right (value < 1 → negative exponent): 0.000098 → 9.8 × 10^-5'},
  {id:'p158',difficulty:'medium',type:'calc',tag:'Calculations/Scientific Notation',q:'Convert 3.4 × 10^-2 to standard notation.',answer:'0.034',isText:true,solution:'Negative exponent: move the decimal left 2 places. 3.4 → 0.034'},
  {id:'p159',difficulty:'medium',type:'multi',tag:'Calculations/Scientific Notation',q:'Multiply (5.4 × 10^3) × (3.0 × 10^-1). Express in scientific notation.',answer:'1.6e3',isText:true,solution:'Multiply coefficients: 5.4 × 3.0 = 16.2. Add exponents: 3 + (−1) = 2. That gives 16.2 × 10^2 = 1.62 × 10^3. Rounded to 2 sig figs: 1.6 × 10^3'},
  {id:'p160',difficulty:'medium',type:'multi',tag:'Calculations/Scientific Notation',q:'Divide (7.2 × 10^5) ÷ (4.0 × 10^2). Express in scientific notation.',answer:'1.8e3',isText:true,solution:'Divide coefficients: 7.2 ÷ 4.0 = 1.8. Subtract exponents: 5 − 2 = 3. Answer: 1.8 × 10^3'},
  {id:'p161',difficulty:'medium',type:'concept',tag:'Concept',q:'Which representation unambiguously shows exactly 2 significant figures?',choices:['400','4.0 × 10^2','4.00 × 10^2','040'],correct:1,solution:'"400" is ambiguous (could be 1, 2, or 3 sig figs). "4.00 × 10^2" clearly shows 3 sig figs. "4.0 × 10^2" clearly shows exactly 2 — the coefficient\'s digits are the only sig figs, and both 4 and 0 are shown deliberately.'},
  {id:'p162',difficulty:'medium',type:'multi',tag:'Multi-step',q:'Add 102.5 + 0.36 + 14, applying the correct sig fig rule.',answer:'117',tolerance:0.5,solution:'Addition: fewest decimal places wins. 102.5 (1 dp), 0.36 (2 dp), 14 (0 dp — limits the answer). Sum = 116.86 → round to 0 decimal places → 117'},
  {id:'p163',difficulty:'medium',type:'multi',tag:'Multi-step',q:'Convert 0.75 hours to seconds.',answer:'2700',tolerance:20,solution:'0.75 hr × (60 min/hr) = 45 min. Then 45 min × (60 s/min) = 2700 s.'},
  {id:'p164',difficulty:'medium',type:'concept',tag:'Properties of Matter',q:'Grinding a sugar cube into a fine powder is an example of:',choices:['A physical change — the chemical composition of sucrose is unchanged','A chemical change — a new substance is formed','A nuclear change','Neither, because sugar cannot change form'],correct:0,solution:'Grinding only changes the size and shape of the particles. The substance is still sucrose (C12H22O11) before and after — no new chemical bonds formed or broke, so this is a physical change.'},
  {id:'p165',difficulty:'medium',type:'concept',tag:'Concept',q:'A dartboard shows three darts clustered tightly together, but far from the bullseye. This illustrates:',choices:['High accuracy, low precision','High precision, low accuracy','High accuracy and high precision','Low accuracy and low precision'],correct:1,solution:'The darts landing close together (clustered) shows high precision — the results are reproducible. But being far from the bullseye (the true value) means low accuracy. Precision and accuracy are independent qualities.'},
  {id:'p166',difficulty:'medium',type:'concept',tag:'Concept',q:'A student\'s balance is not properly zeroed and adds 0.05 g to every measurement they take that day. This type of error is:',choices:['Random error','Systematic error','Human error that cannot be described','Precision error'],correct:1,solution:'A consistent offset applied to every measurement in the same direction is a systematic error, caused here by an uncalibrated instrument. Averaging more trials will not fix it — only recalibrating the balance will.'},
  {id:'p167',difficulty:'medium',type:'multi',tag:'Density & Error',q:'A rectangular block measures 5.0 cm × 2.00 cm × 3.00 cm and has a mass of 150.0 g. Calculate its density in g/cm^3.',answer:'5.0',tolerance:0.1,solution:'V = 5.0 × 2.00 × 3.00 = 30 cm^3, limited to 2 sig figs by the 5.0 cm measurement. D = 150.0 / 30 = 5.0 g/cm^3'},
  {id:'p168',difficulty:'medium',type:'calc',tag:'Calculations/Scientific Notation',q:'Convert 1.20 × 10^-3 m to millimeters.',answer:'1.20',tolerance:0.02,solution:'1.20 × 10^-3 m × (1000 mm/m) = 1.20 mm (3 sig figs)'},
  {id:'p169',difficulty:'medium',type:'concept',tag:'Concept',q:'How many significant figures does 3.0800 × 10^4 contain?',choices:['3','4','5','6'],correct:2,solution:'Every digit in the coefficient of proper scientific notation is significant: 3, 0, 8, 0, 0 — all five digits count, giving 5 sig figs.'},
  {id:'p170',difficulty:'medium',type:'multi',tag:'Multi-step',q:'Convert 0.500 gallons to liters. (1 gal = 3.785 L)',answer:'1.89',tolerance:0.02,solution:'0.500 gal × (3.785 L/gal) = 1.8925 L → round to 3 sig figs (matching 0.500) → 1.89 L'},

  // ── HARD (15) — multi-step chains, combined operations, applied reasoning ──
  {id:'p171',difficulty:'hard',type:'multi',tag:'Multi-step',q:'A patient takes 2 tablets of 325 mg each, twice daily, for 5 days. What is the total medication taken, in grams?',answer:'6.50',tolerance:0.05,solution:'325 mg/tablet × 2 tablets/dose × 2 doses/day × 5 days = 6500 mg. Convert: 6500 mg × (1 g/1000 mg) = 6.50 g'},
  {id:'p172',difficulty:'hard',type:'multi',tag:'Multi-step',q:'Convert 90.0 km/hr to m/s.',answer:'25.0',tolerance:0.2,solution:'90.0 km/hr × (1000 m/km) ÷ (3600 s/hr) = 90,000 / 3600 = 25.0 m/s'},
  {id:'p173',difficulty:'hard',type:'multi',tag:'Density & Error',q:'A student converts a bench length of 6.00 ft to 1.83 m using 1 ft = 0.3048 m. The bench\'s official spec sheet lists 1.80 m. What is the percent error of the converted measurement?',answer:'1.67',tolerance:0.1,solution:'% error = |1.83 − 1.80| / 1.80 × 100% = 0.03 / 1.80 × 100% = 1.67%'},
  {id:'p174',difficulty:'hard',type:'multi',tag:'Multi-step',q:'A car travels 240. km in 3.00 hours. Convert its average speed to m/s.',answer:'22.2',tolerance:0.2,solution:'Speed = 240. km / 3.00 hr = 80.0 km/hr. Convert: 80.0 km/hr × (1000 m/km) ÷ (3600 s/hr) = 22.2 m/s'},
  {id:'p175',difficulty:'hard',type:'multi',tag:'Multi-step',q:'A saline drip delivers 0.150 g of NaCl per mL, at a rate of 2.00 mL/min, for 45.0 minutes. How many grams of NaCl are delivered in total?',answer:'13.5',tolerance:0.2,solution:'0.150 g/mL × 2.00 mL/min = 0.300 g/min. Then 0.300 g/min × 45.0 min = 13.5 g'},
  {id:'p176',difficulty:'hard',type:'multi',tag:'Density & Error',q:'A metal block (mass = 64.0 g) is submerged in a graduated cylinder; the water level rises from 25.0 mL to 33.0 mL. Calculate the density in g/mL — is this closer to aluminum (2.70 g/mL) or iron (7.87 g/mL)?',answer:'8.0',tolerance:0.3,solution:'Volume = 33.0 − 25.0 = 8.0 mL. D = 64.0 / 8.0 = 8.0 g/mL — much closer to iron (7.87) than aluminum (2.70), so the metal is most likely iron.'},
  {id:'p177',difficulty:'hard',type:'multi',tag:'Calculations/Scientific Notation',q:'Evaluate and express in proper scientific notation: (3.20 × 10^-4) × (5.00 × 10^6) ÷ (2.00 × 10^-2)',answer:'8.00e4',isText:true,solution:'Multiply coefficients: 3.20 × 5.00 = 16.0. Add exponents: −4 + 6 = 2, giving 16.0 × 10^2. Divide by 2.00 × 10^-2: coefficients 16.0 ÷ 2.00 = 8.00, exponents 2 − (−2) = 4. Answer: 8.00 × 10^4'},
  {id:'p178',difficulty:'hard',type:'multi',tag:'Multi-step',q:'A pool holds 1.50 × 10^4 gallons of water. Convert this volume to liters and express in proper scientific notation. (1 gal = 3.785 L)',answer:'5.68e4',isText:true,solution:'1.50 × 10^4 gal × (3.785 L/gal) = 56,775 L. Rounded to 3 sig figs and written in scientific notation: 5.68 × 10^4 L'},
  {id:'p179',difficulty:'hard',type:'concept',tag:'Concept',q:'Three trials give sample masses of 12.44 g, 12.46 g, and 12.45 g. The accepted mass is 12.10 g. What does this data set show?',choices:['High accuracy, high precision','High precision, low accuracy','Low precision, high accuracy','Low precision, low accuracy'],correct:1,solution:'The three trials are tightly clustered (12.44–12.46 g), showing high precision. But their average (12.45 g) is well off from the accepted value of 12.10 g, showing low accuracy — a sign of systematic error.'},
  {id:'p180',difficulty:'hard',type:'multi',tag:'Density & Error',q:'A student runs three density trials: 8.10 g/mL, 8.14 g/mL, 8.08 g/mL. The accepted density (nickel) is 8.96 g/mL. Calculate the percent error using the average of the trials.',answer:'9.52',tolerance:0.3,solution:'Average = (8.10 + 8.14 + 8.08) / 3 = 8.107 g/mL. % error = |8.107 − 8.96| / 8.96 × 100% = 0.853 / 8.96 × 100% = 9.52%'},
  {id:'p181',difficulty:'hard',type:'calc',tag:'Calculations/Scientific Notation',q:'Convert 2.5 × 10^-6 kg to milligrams.',answer:'2.5',tolerance:0.05,solution:'2.5 × 10^-6 kg × (1000 g/kg) = 2.5 × 10^-3 g. Then 2.5 × 10^-3 g × (1000 mg/g) = 2.5 mg'},
  {id:'p182',difficulty:'hard',type:'multi',tag:'Multi-step',q:'A vial holds 4 doses of a 12.5 mg/mL solution, 3.00 mL per dose. What is the total mass of drug in the vial, in grams?',answer:'0.150',tolerance:0.005,solution:'12.5 mg/mL × 3.00 mL = 37.5 mg per dose. 37.5 mg/dose × 4 doses = 150 mg total. Convert: 150 mg × (1 g/1000 mg) = 0.150 g'},
  {id:'p183',difficulty:'hard',type:'concept',tag:'Concept',q:'A student times a reaction three times: 45.2 s, 45.3 s, 45.1 s. The accepted literature value is 45.2 s. This data set shows:',choices:['High accuracy AND high precision','High accuracy, low precision','Low accuracy, high precision','Neither accurate nor precise'],correct:0,solution:'The trials are tightly clustered (45.1–45.3 s), showing high precision, and their average (45.2 s) matches the accepted value exactly, showing high accuracy. Good lab technique produces both.'},
  {id:'p184',difficulty:'hard',type:'multi',tag:'Multi-step',q:'A gas flows at a rate of 3.40 L/min. How many liters flow through in 2.50 hours?',answer:'510',tolerance:5,solution:'2.50 hr × (60 min/hr) = 150 min. Then 3.40 L/min × 150 min = 510 L'},
  {id:'p185',difficulty:'hard',type:'multi',tag:'Multi-step',q:'Convert 12.0 inches to centimeters (1 in = 2.54 cm), then add the result to a separate measurement of 5.30 cm. Report the sum with correct sig figs.',answer:'35.8',tolerance:0.2,solution:'12.0 in × 2.54 cm/in = 30.48 cm → rounds to 30.5 cm (3 sig figs). Adding: 30.5 cm (1 dp) + 5.30 cm (2 dp) → limited to 1 decimal place → 35.8 cm'},

  // ═══════════════════════════════════════════════════════
  // HARD EXPANSION BATCH — 30 additional hard problems
  // ═══════════════════════════════════════════════════════
  {id:'p186',difficulty:'hard',type:'multi',tag:'Multi-step',q:'A patient receives a dose of 0.05 mg per kg of body weight, given every 8 hours for 2 days, to a 68 kg patient. What is the total medication received, in mg?',answer:'20.4',tolerance:0.5,solution:'Dose per administration = 0.05 mg/kg × 68 kg = 3.4 mg. Over 2 days (48 hours) every 8 hours = 6 doses. Total = 3.4 mg × 6 = 20.4 mg'},
  {id:'p187',difficulty:'hard',type:'multi',tag:'Density & Error',q:'Three trials give sample masses of 15.62 g, 15.58 g, and 15.65 g. The accepted mass is 15.40 g. Calculate the percent error using the average of the trials.',answer:'1.41',tolerance:0.1,solution:'Average = (15.62 + 15.58 + 15.65) / 3 = 15.617 g. % error = |15.617 − 15.40| / 15.40 × 100% = 0.217 / 15.40 × 100% = 1.41%'},
  {id:'p188',difficulty:'hard',type:'multi',tag:'Multi-step',q:'Convert 3.25 × 10^8 mm to kilometers.',answer:'325',tolerance:2,solution:'3.25 × 10^8 mm × (1 m/1000 mm) = 3.25 × 10^5 m. Then 3.25 × 10^5 m × (1 km/1000 m) = 325 km'},
  {id:'p189',difficulty:'hard',type:'multi',tag:'Calculations/Scientific Notation',q:'Evaluate and express in proper scientific notation: (2.10 × 10^-5) × (4.00 × 10^3) ÷ (3.00 × 10^-2)',answer:'2.80e0',isText:true,solution:'Multiply: 2.10 × 4.00 = 8.40, exponents −5 + 3 = −2, giving 8.40 × 10^-2. Divide by 3.00 × 10^-2: coefficients 8.40 ÷ 3.00 = 2.80, exponents −2 − (−2) = 0. Answer: 2.80 × 10^0'},
  {id:'p190',difficulty:'hard',type:'multi',tag:'Multi-step',q:'A hiker walks at an average pace of 3.2 mi/hr for 2.75 hours. Convert the total distance walked to kilometers. (1 mi = 1.609 km)',answer:'14',tolerance:0.5,solution:'Distance = 3.2 mi/hr × 2.75 hr = 8.8 mi (2 sig figs, limited by 3.2). Convert: 8.8 mi × 1.609 km/mi = 14.16 km → 14 km (2 sig figs)'},
  {id:'p191',difficulty:'hard',type:'multi',tag:'Density & Error',q:'A titration is run three times, requiring 24.65 mL, 24.70 mL, and 24.60 mL. The accepted volume is 25.00 mL. Calculate the percent error using the average of the trials.',answer:'1.40',tolerance:0.1,solution:'Average = (24.65 + 24.70 + 24.60) / 3 = 24.65 mL. % error = |24.65 − 25.00| / 25.00 × 100% = 0.35 / 25.00 × 100% = 1.40%'},
  {id:'p192',difficulty:'hard',type:'calc',tag:'Calculation',q:'Convert 5.00 × 10^-4 L to microliters (μL). (1 L = 10^6 μL)',answer:'500',tolerance:5,solution:'5.00 × 10^-4 L × (10^6 μL/L) = 500 μL. The micro- prefix (μ) means 10^-6, so converting from L requires multiplying by 10^6.'},
  {id:'p193',difficulty:'hard',type:'multi',tag:'Multi-step',q:'A tank is filled at a rate of 0.400 L/min. How many seconds does it take to fill a 2.4 L tank?',answer:'360',tolerance:5,solution:'Time = 2.4 L / 0.400 L/min = 6.00 min. Convert to seconds: 6.00 min × 60 s/min = 360 s'},
  {id:'p194',difficulty:'hard',type:'multi',tag:'Multi-step',q:'A car gets 28.0 miles per gallon. Convert this to kilometers per liter. (1 mi = 1.609 km; 1 gal = 3.785 L)',answer:'11.9',tolerance:0.2,solution:'28.0 mi/gal × 1.609 km/mi = 45.05 km/gal. Then 45.05 km/gal ÷ 3.785 L/gal = 11.9 km/L'},
  {id:'p195',difficulty:'hard',type:'multi',tag:'Density & Error',q:'A sample (mass = 18.70 g) is placed in a graduated cylinder; the level rises from 12.00 mL to 14.50 mL. Calculate the density, then find the percent error compared to the accepted density of zinc (7.14 g/mL).',answer:'4.76',tolerance:0.15,solution:'Volume = 14.50 − 12.00 = 2.50 mL. D = 18.70 / 2.50 = 7.48 g/mL. % error = |7.48 − 7.14| / 7.14 × 100% = 4.76%'},
  {id:'p196',difficulty:'hard',type:'multi',tag:'Multi-step',q:'Convert 3.00 metric tons to pounds. (1 metric ton = 1000 kg; 1 kg = 2.205 lb)',answer:'6620',tolerance:20,solution:'3.00 metric tons × 1000 kg/ton = 3000 kg. Then 3000 kg × 2.205 lb/kg = 6615 lb → 6620 lb (3 sig figs)'},
  {id:'p197',difficulty:'hard',type:'multi',tag:'Multi-step',q:'A syringe delivers 0.75 mL per injection, given 4 times per day, for 2 weeks. What is the total volume delivered, in liters?',answer:'0.042',tolerance:0.001,solution:'0.75 mL × 4 injections/day = 3.0 mL/day. Over 14 days: 3.0 mL/day × 14 days = 42 mL. Convert: 42 mL × (1 L/1000 mL) = 0.042 L'},
  {id:'p198',difficulty:'hard',type:'multi',tag:'Calculations/Scientific Notation',q:'Evaluate: (7.50 × 10^-3) − (2.30 × 10^-4). Express in scientific notation.',answer:'7.27e-3',isText:true,solution:'To subtract, express both numbers with the same exponent: 2.30 × 10^-4 = 0.230 × 10^-3. Then 7.50 × 10^-3 − 0.230 × 10^-3 = 7.27 × 10^-3'},
  {id:'p199',difficulty:'hard',type:'multi',tag:'Balance Reading',q:'A balance\'s zero point drifts by +0.02 g for every hour of continuous use. After 3.5 hours of use, a sample reads 45.87 g on the drifting balance. What is the corrected true mass?',answer:'45.80',tolerance:0.02,solution:'Total drift = 0.02 g/hr × 3.5 hr = 0.07 g. Since the drift adds to every reading, subtract it: 45.87 g − 0.07 g = 45.80 g'},
  {id:'p200',difficulty:'hard',type:'multi',tag:'Multi-step',q:'A stockroom orders 2.50 kg of a chemical priced at $18.40 per 100 g. What is the total cost?',answer:'460.00',tolerance:2,solution:'2.50 kg = 2500 g. Number of 100 g units = 2500 / 100 = 25. Total cost = 25 × $18.40 = $460.00'},
  {id:'p201',difficulty:'hard',type:'multi',tag:'Multi-step',q:'Convert 4.20 × 10^2 °F to Kelvin.',answer:'489',tolerance:1,solution:'First convert to °C: (420 − 32) × 5/9 = 215.6°C. Then to Kelvin: 215.6 + 273 = 488.6 K → 489 K (3 sig figs)'},
  {id:'p202',difficulty:'hard',type:'multi',tag:'Multi-step',q:'A gas sample of 850 mL is drained at a rate of 12.5 mL/s. How long does it take to fully drain, in minutes?',answer:'1.13',tolerance:0.05,solution:'Time = 850 mL / 12.5 mL/s = 68.0 s. Convert to minutes: 68.0 s × (1 min/60 s) = 1.13 min'},
  {id:'p203',difficulty:'hard',type:'multi',tag:'Multi-step',q:'Calculate (8.75 + 0.5) × 2.220, applying the correct sig fig rule at each step.',answer:'21',tolerance:1,solution:'Step 1 (addition): 8.75 (2 dp) + 0.5 (1 dp) = 9.25 → round to 1 dp → 9.3. Step 2 (multiplication): 9.3 (2 sf) × 2.220 (4 sf) = 20.65 → round to 2 sig figs → 21'},
  {id:'p204',difficulty:'hard',type:'multi',tag:'Calculations/Scientific Notation',q:'A stock solution reads 2.50 × 10^2 mg/L. Convert this concentration to g/mL. Express in scientific notation.',answer:'2.50e-4',isText:true,solution:'2.50 × 10^2 mg/L = 250 mg/L. Convert mg → g: 250 mg × (1 g/1000 mg) = 0.250 g/L. Convert L → mL: 0.250 g/L × (1 L/1000 mL) = 2.50 × 10^-4 g/mL'},
  {id:'p205',difficulty:'hard',type:'multi',tag:'Density & Error',q:'An experimental value of 0.0821 is compared to an accepted value of 0.0855. Calculate the percent error.',answer:'3.98',tolerance:0.1,solution:'% error = |0.0821 − 0.0855| / 0.0855 × 100% = 0.0034 / 0.0855 × 100% = 3.98%'},
  {id:'p206',difficulty:'hard',type:'multi',tag:'Multi-step',q:'A container holds 4.50 × 10^4 mm^3 of liquid. Convert this volume to liters. (1 L = 1000 cm^3, and 1 cm^3 = 1000 mm^3)',answer:'0.0450',tolerance:0.0005,solution:'First find the mm^3-to-L factor: 1 L = 1000 cm^3 × 1000 mm^3/cm^3 = 1,000,000 mm^3. So 4.50 × 10^4 mm^3 × (1 L / 1,000,000 mm^3) = 0.0450 L'},
  {id:'p207',difficulty:'hard',type:'multi',tag:'Multi-step',q:'A drug dose is calculated as 5.0 mg per kg of body weight, but the label caps the maximum daily dose at 400 mg regardless of weight. For a 90 kg patient, what dose is actually administered?',answer:'400',tolerance:1,solution:'Calculated dose = 5.0 mg/kg × 90 kg = 450 mg. Since this exceeds the 400 mg safety cap, only 400 mg is administered — the cap overrides the weight-based calculation.'},
  {id:'p208',difficulty:'hard',type:'multi',tag:'Multi-step',q:'A leaking faucet drips 0.20 mL per drop, at a rate of 3 drops per second. How many liters are lost over a full 24-hour day?',answer:'51.8',tolerance:0.5,solution:'Rate = 0.20 mL/drop × 3 drops/s = 0.60 mL/s. Over 24 hr = 86,400 s: 0.60 mL/s × 86,400 s = 51,840 mL = 51.8 L'},
  {id:'p209',difficulty:'hard',type:'multi',tag:'Multi-step',q:'Two masses are measured: 12.6 g and 0.0034 kg. Convert both to grams and find their sum with correct sig figs.',answer:'16.0',tolerance:0.1,solution:'0.0034 kg × 1000 g/kg = 3.4 g. Sum: 12.6 g (1 dp) + 3.4 g (1 dp) = 16.0 g (1 dp — both values already share the same decimal precision)'},
  {id:'p210',difficulty:'hard',type:'multi',tag:'Multi-step',q:'A container holds 250. mL of solution. Evaporation later reduces the total volume by 4.0%. What is the new volume?',answer:'240',tolerance:2,solution:'Volume lost = 250. mL × 0.040 = 10.0 mL. New volume = 250. mL − 10.0 mL = 240. mL (equivalently, 250. × (1 − 0.040) = 240. mL)'},
  {id:'p211',difficulty:'hard',type:'calc',tag:'Calculation',q:'Convert 2.75 × 10^6 μg (micrograms) to grams. (1 g = 10^6 μg)',answer:'2.75',tolerance:0.05,solution:'2.75 × 10^6 μg × (1 g / 10^6 μg) = 2.75 g. The micro- prefix cancels directly with the 10^6 in the given value.'},
  {id:'p212',difficulty:'hard',type:'multi',tag:'Multi-step',q:'A recipe requires 2.00 cups of a chemical solution; a student measures out 1.85 cups. Convert both to mL (1 cup = 236.6 mL) and calculate the percent error of the measured volume.',answer:'7.50',tolerance:0.15,solution:'Required: 2.00 cups × 236.6 mL/cup = 473.2 mL. Measured: 1.85 cups × 236.6 mL/cup = 437.7 mL. % error = |437.7 − 473.2| / 473.2 × 100% = 7.50%'},
  {id:'p213',difficulty:'hard',type:'calc',tag:'Calculation',q:'An electronic pipette has a stated accuracy of ±0.5% at a 200 μL setting. What is the absolute uncertainty, in μL?',answer:'1.0',tolerance:0.05,solution:'Absolute uncertainty = 200 μL × 0.005 (0.5% as a decimal) = 1.0 μL. The pipette\'s true delivered volume falls somewhere between 199.0 and 201.0 μL.'},
  {id:'p214',difficulty:'hard',type:'multi',tag:'Density & Error',q:'A liquid with density 0.879 g/mL fills a graduated cylinder from the 10.0 mL mark to the 45.0 mL mark. Find the sample\'s mass, then convert that mass to pounds. (1 kg = 2.205 lb)',answer:'0.0679',tolerance:0.002,solution:'Volume = 45.0 − 10.0 = 35.0 mL. Mass = 0.879 g/mL × 35.0 mL = 30.8 g = 0.0308 kg. Convert: 0.0308 kg × 2.205 lb/kg = 0.0679 lb'},
  {id:'p215',difficulty:'hard',type:'multi',tag:'Concept',q:'A pressure gauge is miscalibrated and consistently reads 3.0% higher than the true pressure. If the gauge reads 148 psi, what is the true pressure?',answer:'144',tolerance:1,solution:'The reading is 103% of the true value: reading = true × 1.03. So true = 148 / 1.03 = 143.7 psi → 144 psi (3 sig figs). Dividing (not subtracting 3% of 148) correctly undoes a percent-based systematic error.'},
]; // end ALL_PROBLEMS — 215 problems total (125 original + 60 added + 30 hard expansion)
